import re

def parse_json(json_str):
    # Check for syntax errors
    if not re.match(r'^[\{\[].*[\}\]]$', json_str):
        raise ValueError("Invalid JSON syntax")

    # Initialize the result structure
    result = None

    # Parse the JSON string
    if json_str[0] == '{':
        result = parse_object(json_str)
    elif json_str[0] == '[':
        result = parse_array(json_str)
    else:
        result = parse_value(json_str)

    return result

def parse_object(json_str):
    result = {}
    json_str = json_str[1:-1]  # Remove the curly braces
    pairs = json_str.split(',')
    for pair in pairs:
        key, value = pair.split(':')
        key = key.strip().strip('"')
        value = parse_value(value.strip().strip('"'))
        result[key] = value
    return result

def parse_array(json_str):
    result = []
    json_str = json_str[1:-1]  # Remove the square brackets
    elements = json_str.split(',')
    for element in elements:
        element = element.strip().strip('"')
        result.append(parse_value(element))
    return result

def parse_value(json_str):
    if json_str[0] == '"':
        return parse_string(json_str)
    elif json_str[0] == 'n':
        return None
    elif json_str[0] == 't':
        return True
    elif json_str[0] == '-':
        return parse_number(json_str)
    else:
        return parse_number(json_str)

def parse_string(json_str):
    json_str = json_str[1:-1]  # Remove the double quotes
    return json_str

def parse_number(json_str):
    if json_str[0] == '-':
        json_str = json_str[1:]
    return float(json_str)

