import re

def parse_json(json_str):
    # Remove any leading or trailing whitespace
    json_str = json_str.strip()

    # Check if the string starts with '[' or '{'
    if json_str[0] not in ['{', '[']:
        raise ValueError("JSON string must start with '{' or '['")

    # Check if the string ends with '}' or ']'
    if json_str[-1] not in ['}', ']']:
        raise ValueError("JSON string must end with '}' or ']')

    # Remove any leading or trailing quotes
    json_str = json_str.strip('"')

    # Check if the string contains any invalid characters
    if not re.match(r'^[\{\[\]0-9.,\s]+$', json_str):
        raise ValueError("Invalid characters in JSON string")

    # Parse the JSON string
    try:
        return json.loads(json_str)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON string: {e}")

