import re

def parse_json(json_str):
    # Check for syntax errors
    if not re.match(r'^[\{\[].*[\}\]]$', json_str):
        raise SyntaxError("Invalid JSON syntax")

    # Initialize the stack for parsing
    stack = []
    current_value = None
    current_type = None

    # Iterate through each character in the JSON string
    for char in json_str:
        if char == '{':
            stack.append(current_value)
            current_value = {}
            current_type = 'dict'
        elif char == '[':
            stack.append(current_value)
            current_value = []
            current_type = 'list'
        elif char == '"':
            if current_type == 'dict':
                key = ''
                while char != '"':
                    key += char
                    char = next(json_str)
                current_value[key] = parse_json(json_str)
            elif current_type == 'list':
                value = ''
                while char != '"':
                    value += char
                    char = next(json_str)
                current_value.append(parse_json(json_str))
        elif char == ',':
            if current_type == 'dict':
                current_value = stack.pop()
            elif current_type == 'list':
                current_value = stack.pop()
            current_value.append(parse_json(json_str))
        elif char == '}':
            if current_type == 'dict':
                current_value = stack.pop()
            current_value = stack.pop()
        elif char == ']':
            if current_type == 'list':
                current_value = stack.pop()
            current_value = stack.pop()
        elif char == ' ' or char == '\t' or char == '\n':
            continue
        else:
            if current_type == 'dict':
                current_value = stack.pop()
            elif current_type == 'list':
                current_value = stack.pop()
            current_value += char

    return current_value

