def parse_json(json_str):
    # Check if the JSON string starts with '{' or '['
    if not json_str.startswith('{') and not json_str.startswith('['):
        raise ValueError("JSON string must start with '{' or '['")

    # Remove leading and trailing whitespace
    json_str = json_str.strip()

    # Check if the JSON string is empty
    if not json_str:
        raise ValueError("JSON string cannot be empty")

    # Check for balanced braces or brackets
    if json_str.count('{') != json_str.count('}') or json_str.count('[') != json_str.count(']'):
        raise ValueError("JSON string is unbalanced")

    # Check for valid JSON structure
    if json_str.startswith('{'):
        # Parse object
        return parse_object(json_str)
    elif json_str.startswith('['):
        # Parse array
        return parse_array(json_str)
    else:
        # Parse primitive value
        return parse_primitive(json_str)

def parse_object(json_str):
    # Remove the leading '{'
    json_str = json_str[1:]

    # Split the JSON string into key-value pairs
    pairs = json_str.split(',')

    # Parse key-value pairs
    parsed_dict = {}
    for pair in pairs:
        key, value = pair.split(':')
        key = key.strip()
        value = value.strip()

        # Parse value
        parsed_dict[key] = parse_value(value)

    # Remove the trailing '}'
    json_str = json_str[:-1]

    return parsed_dict

def parse_array(json_str):
    # Remove the leading '['
    json_str = json_str[1:]

    # Split the JSON string into elements
    elements = json_str.split(',')

    # Parse elements
    parsed_list = []
    for element in elements:
        element = element.strip()
        parsed_list.append(parse_value(element))

    # Remove the trailing ']'
    json_str = json_str[:-1]

    return parsed_list

def parse_primitive(json_str):
    # Check for boolean value
    if json_str.lower() == 'true':
        return True
    elif json_str.lower() == 'false':
        return False

    # Check for number value
    if re.match(r'^-?\d+(\.\d+)?$', json_str):
        return float(json_str)
    elif re.match(r'^-?\d+$', json_str):
        return int(json_str)

    # Check for string value
    if json_str.startswith('"') and json_str.endswith('"'):
        return json_str[1:-1]

    # Raise ValueError for invalid primitive value
    raise ValueError("Invalid JSON primitive value")

