    if not json_str.startswith('{') and not json_str.startswith('['):
        raise ValueError("JSON string must start with '{' or '['")

    # Remove leading and trailing whitespace
    json_str = json_str.strip()

    # Check if the JSON string is empty
    if not json_str:
        raise ValueError("JSON string cannot be empty")

    # Check if the JSON string ends with '}' or ']'
    if not json_str.endswith('}') and not json_str.endswith(']'):
        raise ValueError("JSON string must end with '}' or ']')

    # Remove the leading and trailing curly braces or square brackets
    json_str = json_str[1:-1]

    # Check if the JSON string contains any invalid characters
    if not re.match(r'^[\{\}[\]\d\w\s,:"\'-]+$', json_str):
        raise ValueError("Invalid characters in JSON string")

    # Parse the JSON string
    if json_str.startswith('{'):
        return parse_object(json_str)
    else:
        return parse_array(json_str)

def parse_object(json_str):
    # Split the JSON string into key-value pairs
    pairs = json_str.split(',')

    # Initialize the dictionary
    obj = {}

    # Iterate over the key-value pairs
    for pair in pairs:
        # Split the key-value pair into key and value
        key, value = pair.split(':')

        # Remove leading and trailing whitespace
        key = key.strip()
        value = value.strip()

        # Check if the key is a valid identifier
        if not re.match(r'^\w+$', key):
            raise ValueError("Invalid identifier in JSON string")

        # Parse the value
        if value.startswith('{'):
            obj[key] = parse_object(value)
        elif value.startswith('['):
            obj[key] = parse_array(value)
        else:
            obj[key] = parse_value(value)

    return obj

def parse_array(json_str):
    # Split the JSON string into elements
    elements = json_str.split(',')

    # Initialize the list
    arr = []

    # Iterate over the elements
    for element in elements:
        # Remove leading and trailing whitespace
        element = element.strip()

        # Check if the element is a valid identifier
        if not re.match(r'^\w+$', element):
            raise ValueError("Invalid identifier in JSON string")

        # Parse the element
        if element.startswith('{'):
            arr.append(parse_object(element))
        elif element.startswith('['):
            arr.append(parse_array(element))
        else:
